"""T1: the content-anchored ARM source preparation on small synthetic trees.

No network and no compilation. The real release tree is prepared by the build.
"""

import json
from pathlib import Path
import subprocess
import sys
import tempfile
import tomllib
import unittest


SCRIPT = Path(__file__).resolve().parent / "prepare_source.py"
REGISTRY = 'source = "registry+https://github.com/rust-lang/crates.io-index"\n'
LOCK = (
    "# This file is automatically @generated by Cargo.\nversion = 4\n\n"
    '[[package]]\nname = "codex-core"\nversion = "0.0.0"\ndependencies = [\n "codex-twin 0.0.0",\n "serde",\n "twin 0.0.0",\n]\n\n'
    '[[package]]\nname = "codex-twin"\nversion = "0.0.0"\n\n'
    '[[package]]\nname = "codex-twin"\nversion = "0.0.0"\n' + REGISTRY + 'checksum = "aa"\n\n'
    '[[package]]\nname = "serde"\nversion = "1.0.0"\n' + REGISTRY + 'checksum = "bb"\n\n'
    '[[package]]\nname = "twin"\nversion = "0.0.0"\n' + REGISTRY + 'checksum = "cc"\n'
)
MANIFEST = (
    '[package]\nname = "codex-core"\n\n[dependencies]\nserde = { workspace = true }\n\n'
    '[target.x86_64-unknown-linux-musl.dependencies]\nopenssl-sys = { workspace = true, features = ["vendored"] }\n\n'
    '[dev-dependencies]\npretty_assertions = { workspace = true }\n'
)
MODES = (
    "fn statx(metadata: Statx) {\n    let kind = u32::from(metadata.stx_mode) & libc::S_IFMT;\n"
    "    if kind == libc::S_IFLNK {\n        return;\n    }\n    let file = kind == libc::S_IFREG;\n}\n"
    "fn fstatat(metadata: Stat) {\n    let kind = metadata.st_mode & libc::S_IFMT;\n"
    "    let directory = kind == libc::S_IFDIR;\n}\n"
)
WIDENED = (
    "fn statx(metadata: Statx) {\n    let kind = u32::from(metadata.stx_mode) & u32::from(libc::S_IFMT);\n"
    "    if kind == u32::from(libc::S_IFLNK) {\n        return;\n    }\n    let file = kind == u32::from(libc::S_IFREG);\n}\n"
    "fn fstatat(metadata: Stat) {\n    let kind = metadata.st_mode & u32::from(libc::S_IFMT);\n"
    "    let directory = kind == u32::from(libc::S_IFDIR);\n}\n"
)
HOSTS = 'any(target_os = "windows", target_os = "linux", target_os = "macos")'
ENGINE = f"mod dispatch;\n#[cfg({HOSTS})]\nmod run;\n"
DISPATCH = (
    f"fn ensure_host_supported() -> Result<(), Error> {{\n    #[cfg({HOSTS})]\n    {{\n        Ok(())\n    }}\n"
    f"    #[cfg(not({HOSTS}))]\n    {{\n        Err(Error::unsupported())\n    }}\n}}\n"
    "pub fn spawn(request: &Request, logger: &mut Logger) -> Result<(), Error> {\n"
    "    ensure_host_supported()?;\n    crate::mxc_engine::run::log_policy_hash(request, logger);\n    Ok(())\n}\n"
)
GATED = DISPATCH.replace("    crate::mxc_engine::run::", f"    #[cfg({HOSTS})]\n    crate::mxc_engine::run::")
MXC = "git+https://github.com/microsoft/mxc?rev=abc#abc"


class PrepareSourceTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix="codex prepare ")
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.files = {
            "codex-rs/Cargo.toml": '[workspace.package]\nversion = "0.200.1"\n',
            "codex-rs/Cargo.lock": LOCK,
            "codex-rs/core/Cargo.toml": MANIFEST,
            "codex-rs/exec-server/src/no_follow/unix.rs": MODES,
        }

    def prepare(self, **changed):
        self.files.update(changed)
        for name, text in self.files.items():
            path = self.root / name
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text)
        return subprocess.run([sys.executable, str(SCRIPT), str(self.root)],
                              text=True, capture_output=True, timeout=10)

    def read(self, name):
        return (self.root / name).read_text()

    def assert_refused(self, result, diagnostic):
        self.assertEqual(result.returncode, 1, result.stdout + result.stderr)
        self.assertEqual(result.stdout, "")
        self.assertEqual(result.stderr, "build-codex-armv7: " + diagnostic + "\n")
        # A refusal leaves every later file as the release shipped it.
        self.assertEqual(self.read("codex-rs/exec-server/src/no_follow/unix.rs"),
                         self.files["codex-rs/exec-server/src/no_follow/unix.rs"])

    def test_any_release_is_prepared_by_content(self):
        result = self.prepare()
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(result.stdout, "prepare-source: version=0.200.1 local_lock_entries=2 "
                                        "openssl=vendored-armv7 mode_constants_widened=5\n")
        # Local entries and the local half of an ambiguous dependency move; the
        # registry crates that share a name or the placeholder version do not.
        self.assertEqual(self.read("codex-rs/Cargo.lock"), LOCK
                         .replace('name = "codex-core"\nversion = "0.0.0"', 'name = "codex-core"\nversion = "0.200.1"')
                         .replace('name = "codex-twin"\nversion = "0.0.0"\n\n', 'name = "codex-twin"\nversion = "0.200.1"\n\n')
                         .replace('"codex-twin 0.0.0"', '"codex-twin 0.200.1"'))
        self.assertEqual(self.read("codex-rs/core/Cargo.toml"), MANIFEST + (
            "\n# Build OpenSSL from source for the Android ARMv7 deployment.\n"
            "[target.armv7-linux-androideabi.dependencies]\n"
            'openssl-sys = { workspace = true, features = ["vendored"] }\n'))
        manifest = tomllib.loads(self.read("codex-rs/core/Cargo.toml"))
        self.assertEqual(sorted(manifest["target"]), ["armv7-linux-androideabi", "x86_64-unknown-linux-musl"])
        self.assertEqual(self.read("codex-rs/exec-server/src/no_follow/unix.rs"), WIDENED)

    def test_shifted_lines_and_an_already_aligned_lock_still_apply(self):
        result = self.prepare(**{
            "codex-rs/Cargo.lock": LOCK.replace('name = "codex-core"\nversion = "0.0.0"',
                                                'name = "codex-core"\nversion = "0.200.1"'),
            "codex-rs/exec-server/src/no_follow/unix.rs": "// moved\n" * 40 + MODES,
        })
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(self.read("codex-rs/exec-server/src/no_follow/unix.rs"), "// moved\n" * 40 + WIDENED)
        self.assertNotIn('version = "0.0.0"\n\n', self.read("codex-rs/Cargo.lock"))

    def test_a_local_entry_at_another_version_is_refused(self):
        lock = LOCK.replace('name = "codex-core"\nversion = "0.0.0"', 'name = "codex-core"\nversion = "0.160.0"')
        self.assert_refused(self.prepare(**{"codex-rs/Cargo.lock": lock}),
                            "local package codex-core is locked at 0.160.0; expected 0.200.1")
        self.assertEqual(self.read("codex-rs/Cargo.lock"), lock)
        self.assertEqual(self.read("codex-rs/core/Cargo.toml"), MANIFEST)

    def test_missing_openssl_anchor_and_existing_android_table_are_refused(self):
        gone = MANIFEST.replace(', features = ["vendored"]', "")
        self.assert_refused(self.prepare(**{"codex-rs/core/Cargo.toml": gone}),
                            "OpenSSL anchor missing: core/Cargo.toml no longer vendors openssl-sys for any target")
        self.assertEqual(self.read("codex-rs/core/Cargo.toml"), gone)
        present = MANIFEST + "\n[target.armv7-linux-androideabi.dependencies]\nlibc = { workspace = true }\n"
        self.assert_refused(self.prepare(**{"codex-rs/core/Cargo.toml": present}),
                            "OpenSSL step is stale: core/Cargo.toml already has an Android ARMv7 dependency table")

    def test_missing_or_unrecognised_mode_anchors_are_refused(self):
        name = "codex-rs/exec-server/src/no_follow/unix.rs"
        statx = "u32::from(metadata.stx_mode) & libc::S_IFMT"
        fstatat = "metadata.st_mode & libc::S_IFMT"
        for text, diagnostic in [
            (MODES.replace(statx, "metadata.kind()"),
             f"mode-width anchor missing: the statx path no longer reads `{statx}`"),
            (MODES.replace(fstatat, "metadata.kind()"),
             f"mode-width anchor missing: the fstatat path no longer reads `{fstatat}`"),
            (MODES + "const MASK: u32 = libc::S_IFMT as u32;\n",
             "mode-width step is stale: a libc mode constant is used outside a mask or comparison"),
        ]:
            with self.subTest(diagnostic=diagnostic):
                self.assert_refused(self.prepare(**{name: text}), diagnostic)
        (self.root / name).unlink()
        del self.files[name]
        result = self.prepare()
        self.assertEqual(result.stderr, "build-codex-armv7: mode-width anchor missing: " + name + "\n")


class VendorMxcTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix="codex mxc ")
        self.addCleanup(self.temp.cleanup)
        self.work = Path(self.temp.name) / "work"
        self.checkout = Path(self.temp.name) / "cargo/git/checkouts/mxc-1/abc"
        self.sdk = self.checkout / "src/mxc-sdk"
        engine = self.sdk / "src/core/mxc_engine"
        engine.mkdir(parents=True)
        self.work.mkdir()
        (self.checkout / ".cargo-ok").write_text("")
        (self.checkout / ".git").mkdir()
        (self.checkout / "src/Cargo.toml").write_text("[workspace]\n")
        (self.sdk / "Cargo.toml").write_text("[package]\nname = 'mxc-sdk'\n")
        (engine / "mod.rs").write_text(ENGINE)
        (engine / "dispatch.rs").write_text(DISPATCH)
        (self.work / "cargo-config.toml").write_text('paths = ["/work/vendor/pagable-0.4.1"]\n')

    def vendor(self, source=MXC, name="mxc-sdk"):
        package = {"name": name, "source": source, "manifest_path": str(self.sdk / "Cargo.toml")}
        (self.work / "metadata.json").write_text(json.dumps({"packages": [package]}))
        return subprocess.run([sys.executable, str(SCRIPT), "--mxc", str(self.work)],
                              text=True, capture_output=True, timeout=10)

    def dispatch(self, root):
        return (root / "src/mxc-sdk/src/core/mxc_engine/dispatch.rs").read_text()

    def test_the_locked_checkout_is_vendored_with_only_the_host_gate(self):
        result = self.vendor()
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(result.stdout, "prepare-source: mxc-sdk=abc android_gates=1\n")
        vendor = self.work / "vendor/mxc"
        self.assertEqual(self.dispatch(vendor), GATED)
        # Cargo's own checkout is untouched, and git metadata is not copied.
        self.assertEqual(self.dispatch(self.checkout), DISPATCH)
        self.assertFalse((vendor / ".git").exists())
        self.assertEqual((vendor / "src/Cargo.toml").read_text(), "[workspace]\n")
        self.assertEqual(tomllib.loads((self.work / "cargo-config.toml").read_text()),
                         {"paths": ["/work/vendor/pagable-0.4.1", str(vendor / "src/mxc-sdk")]})

    def test_a_release_without_the_fault_is_left_alone(self):
        config = (self.work / "cargo-config.toml").read_text()
        for change, message in [
            (lambda: (self.sdk / "src/core/mxc_engine/dispatch.rs").write_text(GATED),
             "prepare-source: mxc-sdk needs no Android gate\n"),
            (None, "prepare-source: mxc-sdk is not locked by this release\n"),
        ]:
            result = change() and self.vendor() if change else self.vendor(name="other")
            self.assertEqual((result.returncode, result.stdout), (0, message), result.stderr)
            self.assertFalse((self.work / "vendor").exists())
            self.assertEqual((self.work / "cargo-config.toml").read_text(), config)

    def test_a_changed_engine_or_source_is_refused(self):
        engine = self.sdk / "src/core/mxc_engine"
        stale = "build-codex-armv7: mxc step is stale: "
        cases = [
            (lambda: None, {"source": "registry+https://github.com/rust-lang/crates.io-index"},
             stale + "mxc-sdk is not the single locked git checkout\n"),
            (lambda: (engine / "mod.rs").write_text("mod dispatch;\nmod run;\n"), {},
             stale + "the engine no longer configures `run` out by host\n"),
            (lambda: (engine / "dispatch.rs").write_text(DISPATCH.replace("    ensure_host_supported()?;\n", "")), {},
             stale + "a use of `run` is not a statement behind the host check\n"),
            (lambda: (engine / "dispatch.rs").write_text(DISPATCH + "use crate::mxc_engine::run::Runner;\n"), {},
             stale + "a use of `run` is not a statement behind the host check\n"),
        ]
        for change, arguments, diagnostic in cases:
            with self.subTest(diagnostic=diagnostic):
                (engine / "mod.rs").write_text(ENGINE)
                (engine / "dispatch.rs").write_text(DISPATCH)
                change()
                result = self.vendor(**arguments)
                self.assertEqual((result.returncode, result.stdout, result.stderr), (1, "", diagnostic))
                self.assertFalse((self.work / "vendor").exists())


if __name__ == "__main__":
    unittest.main()
